def populate_instructor_slugs(apps, schema_editor):
    from django.utils.text import slugify

    instructor_profile = apps.get_model("mentoring", "InstructorProfile")
    for profile in instructor_profile.objects.filter(slug__isnull=True):
        base = slugify(profile.professional_name)[:150] or "mentor"
        candidate = base
        if instructor_profile.objects.filter(slug=candidate).exclude(pk=profile.pk).exists():
            candidate = f"{base}-{str(profile.pk)[:8]}"
        profile.slug = candidate
        profile.save(update_fields=["slug"])


